package com.bank.net;

import java.io.*;

public class ConnectionManager implements Serializable {
    private static final long serialVersionUID = 1L;

    private String endpoint;                        // persisted normally

    // transient: runtime-only state, not persisted.
    // volatile:  shared across threads, writes instantly visible to readers.
    private transient volatile boolean connected;   // BOTH modifiers — orthogonal concerns

    // transient does NOT make this secure for JSON/logs/DB — demonstrated below.
    private transient String password;

    public ConnectionManager(String endpoint, String password) {
        this.endpoint = endpoint;
        this.password = password;
        this.connected = false;
    }

    public void setConnected(boolean c) { this.connected = c; } // volatile write → visible to all
    public boolean isConnected() { return connected; }          // volatile read → latest value
    public String getEndpoint() { return endpoint; }
    public String getPassword() { return password; }

    // A naive toString / JSON would LEAK the transient password — transient is not security.
    @Override
    public String toString() {
        // Deliberately naive to demonstrate the leak (do NOT do this in real code).
        return "ConnectionManager{endpoint=" + endpoint + ", password=" + password
               + ", connected=" + connected + "}";
    }

    // Simulate a JSON serializer that ignores 'transient' (like Jackson by default).
    public String toNaiveJson() {
        return "{\"endpoint\":\"" + endpoint + "\",\"password\":\"" + password
               + "\",\"connected\":" + connected + "}";
    }
}
