package com.bank.net;

import java.io.*;
import java.util.logging.*;

public class VolatileTransientDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        ConnectionManager cm = new ConnectionManager("bank-core:5432", "SuperSecret123");

        // 1) VOLATILE: one thread flips 'connected', another sees it promptly.
        Thread worker = new Thread(() -> {
            while (!cm.isConnected()) { /* spin: volatile read sees the update */ }
            log.info("Worker observed connected=true (volatile visibility worked).");
        });
        worker.start();
        Thread.sleep(50);
        cm.setConnected(true); // volatile write
        worker.join(1000);

        // 2) TRANSIENT: serialization skips 'connected' (and 'password').
        byte[] bytes;
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(cm);
            bytes = baos.toByteArray();
        }
        ConnectionManager restored;
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            restored = (ConnectionManager) ois.readObject();
        }
        log.info(() -> "AFTER deserialize: endpoint=" + restored.getEndpoint()
                        + " connected=" + restored.isConnected()
                        + " (false default — transient skipped it)");
        log.info(() -> "AFTER deserialize: password=" + restored.getPassword()
                        + " (null — transient skipped native serialization)");

        // 3) transient is NOT security — JSON and toString STILL leak the password.
        log.severe(() -> "LEAK via naive JSON: " + cm.toNaiveJson());
        log.severe(() -> "LEAK via toString(): " + cm);
        log.warning("transient only blocked NATIVE serialization — JSON/toString/logs/DB still leak.");
    }
}
